/* HARDGATE — build stamp. Single source of truth for "which version am I running?"
   Loaded FIRST so every later script can read G.HG_BUILD. */
(function(){
'use strict';
var G = (typeof window !== 'undefined') ? window : globalThis;

var HG_BUILD = {
  version: 'hg-v948',
  pack: 'OPTI GOLD SCORED THE EXIT OF EVERY SETUP UNDER AN INFINITE HORIZON, ON SETUPS THAT ALL EXPIRE. Working the gold desk list again, this is the one minting desk with no gold-native filter of any kind and no walk artifact -- and the defect is in the number it RANKS by. ogProb scores two legs. The fill leg has always been distance and horizon aware, the reflection principle on the bars remaining. The outcome leg was the constant 1 over (1 plus rr) -- gamblers ruin between two absorbing barriers, which is the answer GIVEN that one of them is reached AT ALL. These setups die at horizonBars whether or not either was, so that constant is an UPPER BOUND and never the value. It was also blind to HOW FAR the target is: driven through the real function, a target 20xATR away with one bar left and one 0.5xATR away with forty both scored 0.333, and the desk rated the hopeless one at 0.307 against 0.329. One estimator applied to one leg and omitted from the other. THE DIRECTION NEEDS NO MEASUREMENT, ONLY ARITHMETIC: the target sits rr R away and the stop 1R, so truncating at a finite horizon removes winners at least as readily as losers and the figure can only be too high. QUANTIFIED on the repo only real gold book, 9,897 OMNIGOLD plans at the same 2R: at a 16-bar horizon winners are censored more than losers in 4 of 4 disjoint windows -- 30.1 vs 22.0, 30.8 vs 23.3, 26.7 vs 22.7, 24.3 vs 17.3 per cent -- but at 32 and 48 bars it is 3 of 4, NOT unanimous. So the sign is arithmetic and the MAGNITUDE carries no verdict: no number from that walk is baked here or gated on, and that population is OMNIGOLD gates rather than this rule. THE FIX IS THE FILE OWN ESTIMATOR ON BOTH LEGS. P(win given fill) becomes the min of 1 over (1 plus rr) and the chance of travelling to the target within the bars that remain -- the same reflection form, stated once instead of written twice. It is a bound made of two bounds, so it can only LOWER the number and no setup can be made to look better than this desk already claimed; across 360 distance by horizon by R:R combinations it never exceeds the old figure and never leaves 0 to 1. Where the horizon is ample it returns EXACTLY the old value and nothing moves. WHAT THE CHANGE MAKES WORSE, SAID ON THE CARD: the driftless assumption used to bite only the fill leg over short distances, and now applies over long ones where a driftless model is least like gold. So the LEVEL is a bound that may sit far below the truth; what survives is the ORDERING, which is all this number is used for, and the old figure stays on the row as condInf so the reader sees both and the gap. THREE INSTANCES OF THE SAME +null===0 TRAP, ALL FOUND BY MY OWN CHECKS AND THE EXISTING SUITE: an absent t1 read as a target 575xATR from a 2300 entry and produced a confident bound of zero; an absent barsLeft in ogTravelP read as expired; and the pre-existing resting guard did the same. ABSENT is now distinct from EXPIRED everywhere -- unreadable yields no estimate or falls back to the infinite-horizon figure, never a smaller number invented in its place. MEASURED EFFECT on the real rule over 60 scans of a tape: the horizon binds on 75.0 per cent of resting estimates and changes nothing on the other 25.0; median p 0.061 to 0.046; the lane leader changes on odds alone in 2 of 16 contests. THE TAPE IS SYNTHETIC, because every data route here is 403 CONNECT, so that is weak evidence of FREQUENCY and is not offered as more -- the behaviour is proved by driving the real ogSignals, ogProb and ogTopPicks. NOTHING LEAVES THE BOARD: ogProb ranks and renders, it never mints, and no gate, threshold or verdict moves on any desk. Tests: tests/test-optigold-horizon-bound.mjs, 34 assertions, 12 of 12 behavioural mutations caught with the baseline verified green first',
  built: '2026-09-24T00:00:00Z'
};

function hgBuildLabel(b){
  b = b || HG_BUILD;
  var v = String(b.version || '').replace(/^hg-/, '');
  var p = b.pack ? ' · ' + b.pack : '';
  return v ? v + p : 'unknown build';
}

function hgBuildParseVersion(text){
  try{
    if (typeof text !== 'string' || !text) return null;
    var m = text.match(/version\s*:\s*['"]([A-Za-z0-9._-]{1,64})['"]/);
    return m ? m[1] : null;
  }catch(e){ return null; }
}

function hgBuildCompare(loaded, live){
  if (!loaded || !live) return { state: 'unknown', reason: 'could not read one side' };
  if (String(loaded) === String(live)) return { state: 'fresh', reason: 'matches server' };
  return { state: 'stale', reason: 'server is on ' + live + ', this tab loaded ' + loaded };
}

function hgBuildDistance(loaded, live){
  try{
    var a = String(loaded || '').match(/(\d+)\s*$/);
    var b = String(live || '').match(/(\d+)\s*$/);
    if (!a || !b) return null;
    return (+b[1]) - (+a[1]);
  }catch(e){ return null; }
}

function hgBuildChipState(res, b){
  b = b || HG_BUILD;
  var label = hgBuildLabel(b);
  if (!res || res.state === 'pending') return { text: label, cls: 'ok', title: 'checking for newer build' };
  if (res.state === 'fresh') return { text: label, cls: 'ok', title: 'running current build (' + res.live + ')' };
  if (res.state === 'stale'){
    var d = hgBuildDistance(res.loaded, res.live);
    var behind = (d != null && d > 0) ? ' (' + d + ' behind)' : '';
    return { text: label + ' · STALE' + behind, cls: 'bad', title: res.reason + ' — hard-reload to pick it up' };
  }
  return { text: label + ' · ?', cls: 'warn', title: (res.reason || 'freshness unknown') + ' — offline or blocked' };
}

function hgBuildFreshness(fetchImpl){
  var f = (typeof fetchImpl === 'function') ? fetchImpl : (typeof G.fetch === 'function' ? G.fetch.bind(G) : null);
  var loaded = HG_BUILD.version;
  if (!f) return Promise.resolve({ state: 'unknown', loaded: loaded, live: null, reason: 'no fetch' });
  var url = './build-stamp.js?fresh=' + Date.now();
  return f(url, { cache: 'no-store' }).then(function(res){
    if (!res || !res.ok) throw new Error('http ' + (res && res.status));
    return res.text();
  }).then(function(text){
    var live = hgBuildParseVersion(text);
    var cmp = hgBuildCompare(loaded, live);
    return { state: cmp.state, loaded: loaded, live: live, reason: cmp.reason };
  }).catch(function(e){
    return { state: 'unknown', loaded: loaded, live: null, reason: (e && e.message) || 'network failed' };
  });
}

function hgBuildSwWaiting(){
  try{
    var sw = G.navigator && G.navigator.serviceWorker;
    if (!sw || !sw.controller) return Promise.resolve(false);
    return sw.getRegistration().then(function(reg){
      return !!(reg && reg.waiting);
    }).catch(function(){ return false; });
  }catch(e){ return Promise.resolve(false); }
}

function hgRenderBuildChip(el, res){
  try{
    var node = el || (G.document && G.document.getElementById('chipBuild'));
    if (!node) return null;
    var st = hgBuildChipState(res);
    node.textContent = '';
    var b = G.document.createElement('b');
    b.textContent = st.text;
    node.appendChild(b);
    node.title = st.title;
    node.className = 'statuschip hg-build-' + st.cls;
    return st;
  }catch(e){ return null; }
}

function hgRenderVerBadge(res){
  try{
    var node = G.document && G.document.getElementById('hgVerBadge');
    if (!node) return null;
    var v = String(HG_BUILD.version || '').replace(/^hg-/, '');
    if (!v){ node.style.display = 'none'; return null; }
    if (res && res.state === 'stale'){
      var d = hgBuildDistance(res.loaded, res.live);
      var behind = (d != null && d > 0) ? ' (' + d + ' behind)' : '';
      node.textContent = v + ' · STALE' + behind;
      node.className = 'verbadge verbadge-stale';
      node.title = (res.reason || 'stale') + ' — reloading…';
      return { stale: true };
    }
    node.textContent = v;
    node.className = 'verbadge';
    node.title = HG_BUILD.version + (HG_BUILD.pack ? (' · ' + HG_BUILD.pack) : '');
    return { stale: false };
  }catch(e){ return null; }
}

function hgBuildMaybeReload(res, storage, reloadFn){
  try{
    if (!res || res.state !== 'stale' || !res.live) return false;
    var store = storage;
    if (!store && G.sessionStorage) store = G.sessionStorage;
    if (!store || typeof store.getItem !== 'function') return false;
    var key = 'hg_build_reload_' + String(res.live);
    if (store.getItem(key)) return false;
    var reload = reloadFn;
    if (!reload && G.location && typeof G.location.reload === 'function') reload = G.location.reload.bind(G.location);
    if (typeof reload !== 'function') return false;
    store.setItem(key, '1');
    reload();
    return true;
  }catch(e){}
  return false;
}

function hgBuildApplyFreshness(res){
  try{
    if (!res) return res;
    hgRenderBuildChip(null, res);
    hgRenderVerBadge(res);
    G.HG_BUILD_FRESHNESS = res;
    hgBuildMaybeReload(res);
    return res;
  }catch(e){ return res; }
}

function hgBuildInit(){
  try{
    hgRenderBuildChip(null, null);
    hgRenderVerBadge(null);
    hgBuildFreshness().then(function(res){
      return hgBuildSwWaiting().then(function(waiting){
        if (waiting && res.state === 'fresh'){
          res = { state: 'stale', loaded: res.loaded, live: res.live, reason: 'new build downloaded' };
        }
        return hgBuildApplyFreshness(res);
      });
    });
    if (G.document && typeof G.document.addEventListener === 'function'){
      G.document.addEventListener('visibilitychange', function(){
        try{
          if (!G.document || G.document.visibilityState !== 'visible') return;
          hgBuildFreshness().then(hgBuildApplyFreshness);
        }catch(e){}
      });
    }
  }catch(e){}
}

G.HG_BUILD = HG_BUILD;
G.hgBuildLabel = hgBuildLabel;
G.hgBuildParseVersion = hgBuildParseVersion;
G.hgBuildCompare = hgBuildCompare;
G.hgBuildDistance = hgBuildDistance;
G.hgBuildChipState = hgBuildChipState;
G.hgBuildFreshness = hgBuildFreshness;
G.hgBuildSwWaiting = hgBuildSwWaiting;
G.hgRenderBuildChip = hgRenderBuildChip;
G.hgRenderVerBadge = hgRenderVerBadge;
G.hgBuildMaybeReload = hgBuildMaybeReload;
G.hgBuildApplyFreshness = hgBuildApplyFreshness;
G.hgBuildInit = hgBuildInit;

try{
  if (G.document){
    if (G.document.readyState === 'loading'){
      G.document.addEventListener('DOMContentLoaded', hgBuildInit);
    } else {
      hgBuildInit();
    }
  }
}catch(e){}

})();
